public static void selectionSort(int[] r) {
    for (int i = 0; i < r.length - 1; i++) {
        int minIndex = i;
        for (int j = i + 1; j < r.length; j++) {
            if (r[j] < r[minIndex]) {
                minIndex = j;
            }
        }
        if (minIndex != i) {
            tausche(r, i, minIndex);
        }
    }
}

public static void insertionSort(int[] r) {
    for (int i = 1; i < r.length; i++) {
        int j = i;
        while (j > 0 && r[j] < r[j - 1]) {
            tausche(r, j, j - 1);
            j--;
        }
    }
}

public static void bubbleSort(int[] r) {
    boolean getauscht = true;
    int durchlauf = 0;
    while (getauscht) {
        getauscht = false;
        for (int j = 0; j < r.length - 1 - durchlauf; j++) {
            if (r[j + 1] < r[j]) {
                tausche(r, j, j + 1);
                getauscht = true;
            }
        }
        durchlauf++;
    }
}

public static int binaer(int[] r, int x) {
    int lo = 0;
    int hi = r.length - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;  // → Tabellenzeile
        if (r[mid] == x) {
            return mid;
        }
        if (r[mid] < x) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}
